<!doctype html><html><head><meta charset="utf-8"><title>Login - Jura Server Guard</title><style>body{font-family:system-ui;background:#0f172a;color:#e2e8f0;display:grid;place-items:center;height:100vh}.card{background:#1e293b;padding:30px;border-radius:14px;width:360px}input{width:100%;padding:10px;margin:8px 0;background:#020617;color:#fff;border:1px solid #334155;border-radius:6px}button{width:100%;padding:10px;background:#2563eb;color:#fff;border:0;border-radius:6px}.lang-switch{display:flex;gap:8px;justify-content:center;margin-top:14px}.lang-switch a{padding:2px 8px;border-radius:4px;font-size:12px;text-decoration:none;color:#94a3b8}.lang-switch a.active{background:#334155;color:#e2e8f0}</style></head><body><form class="card" method="post"><h1>Jura Server Guard</h1><p><?= e(t('Admin login required.')) ?></p><?php if(!empty($error)): ?><p style="color:#fca5a5"><?= e(t($error)) ?></p><?php endif ?><input name="email" type="email" placeholder="admin@example.com" required><input name="password" type="password" placeholder="<?= e(t('Password')) ?>" required><button><?= e(t('Login')) ?></button><div class="lang-switch"><?php foreach(available_locales() as $code=>$label): ?><a href="/lang/<?= e($code) ?>" class="<?= current_locale()===$code?'active':'' ?>"><?= e(strtoupper($code)) ?></a><?php endforeach ?></div></form></body></html>
